func (t *CompanyInformation) ChangeCompany(company string) bool {
	if !tables.CompanyExists(t.db, t.dbType, company) {
		return false
	}
	t.company = company
	return true
}

// TestField returns an error unless the field has a value — or, with a value, that value
// (TestField): the user's messages "X is required" / "X must be …"
func (t *CompanyInformation) TestField(fieldName string, value ...any) error {
	no := t.FieldNo(fieldName)
	current, ok := t.FieldValue(no)
	if !ok {
		// a FlowField: its value as CalcFields left it (classic TESTFIELD after CALCFIELDS)
		current, ok = t.flowFieldValue(no)
	}
	if !ok {
		return fmt.Errorf("TestField: %s is not a field of Company_Information", fieldName)
	}
	field := t.FieldName(no)
	if len(value) == 0 {
		if tables.IsEmptyValue(current) {
			return apperrors.FieldRequired(CompanyInformationTableName, field)
		}
		return nil
	}
	if !tables.SameValue(current, value[0]) {
		return apperrors.FieldMustBeValue(CompanyInformationTableName, field, value[0])
	}
	return nil
}

